Set-Location -Path $PSScriptRoot
python -c "import json; from pathlib import Path; from playwright.sync_api import sync_playwright; p=sync_playwright().start(); ctx=p.chromium.launch_persistent_context(user_data_dir=str(Path('perfil_bfn').resolve()), headless=False); page=ctx.pages[0] if ctx.pages else ctx.new_page(); page.goto('https://survey.bfn-fusion.bigdutchman.com/', wait_until='domcontentloaded', timeout=60000); print('Inicia sesion si lo pide...'); page.wait_for_url('**/survey.bfn-fusion.bigdutchman.com/**', timeout=180000); page.wait_for_selector('table', state='attached', timeout=60000); page.wait_for_timeout(4000); estado=ctx.storage_state(); Path('sesion_bfn.json').write_text(json.dumps(estado, separators=(',', ':')), encoding='utf-8'); ctx.close(); p.stop(); print('OK: sesion_bfn.json actualizado')"
if (Test-Path .\sesion_bfn.json) { Get-Content .\sesion_bfn.json -Raw | Set-Clipboard; Write-Host 'LISTO: Copiado al portapapeles. Pegalo en GitHub Secret MAMAY_BFN_SESSION' -ForegroundColor Green }
